func (o AccessTokenSlice) UpdateAll(ctx context.Context, exec bob.Executor, vals AccessTokenSetter) error {
	if len(o) == 0 {
		return nil
	}

	_, err := AccessTokens.Update(vals.UpdateMod(), o.UpdateMod()).All(ctx, exec)
	return err
}

func (o AccessTokenSlice) DeleteAll(ctx context.Context, exec bob.Executor) error {
	if len(o) == 0 {
		return nil
	}

	_, err := AccessTokens.Delete(o.DeleteMod()).Exec(ctx, exec)
	return err
}

func (o AccessTokenSlice) ReloadAll(ctx context.Context, exec bob.Executor) error {
	if len(o) == 0 {
		return nil
	}

	o2, err := AccessTokens.Query(sm.Where(o.pkIN())).All(ctx, exec)
	if err != nil {
		return err
	}

	o.copyMatchingRows(o2...)

	return nil
}

// SubjectIdentityUser starts a query for related objects on identity_users
func (o *AccessToken) SubjectIdentityUser(mods ...bob.Mod[*dialect.SelectQuery]) IdentityUsersQuery {
	return IdentityUsers.Query(append(mods,
		sm.Where(IdentityUsers.Columns.ID.EQ(psql.Arg(o.Subject))),
	)...)
}

func (os AccessTokenSlice) SubjectIdentityUser(mods ...bob.Mod[*dialect.SelectQuery]) IdentityUsersQuery {
	pkSubject := make(pgtypes.Array[string], 0, len(os))

	// the array is only a filter (semi-join), so duplicate keys can be
	// dropped before they are sent over the wire
	seenSubject := make(map[string]struct{}, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}
		if _, ok := seenSubject[o.Subject]; ok {
			continue
		}
		seenSubject[o.Subject] = struct{}{}
		pkSubject = append(pkSubject, o.Subject)
	}
	PKArgExpr := psql.Any(psql.Cast(psql.Arg(pkSubject), "text[]"))

	return IdentityUsers.Query(append(mods,
		sm.Where(IdentityUsers.Columns.ID.EQ(PKArgExpr)),
	)...)
}

func attachAccessTokenSubjectIdentityUser0(ctx context.Context, exec bob.Executor, count int, accessToken0 *AccessToken, identityUser1 *IdentityUser) (*AccessToken, error) {
	setter := &AccessTokenSetter{
		Subject: omit.From(identityUser1.ID),
	}

	err := accessToken0.Update(ctx, exec, setter)
	if err != nil {
		return nil, fmt.Errorf("attachAccessTokenSubjectIdentityUser0: %w", err)
	}

	return accessToken0, nil
}

func (accessToken0 *AccessToken) InsertSubjectIdentityUser(ctx context.Context, exec bob.Executor, related *IdentityUserSetter) error {
	var err error

	identityUser1, err := IdentityUsers.Insert(related).One(ctx, exec)
	if err != nil {
		return fmt.Errorf("inserting related objects: %w", err)
	}

	_, err = attachAccessTokenSubjectIdentityUser0(ctx, exec, 1, accessToken0, identityUser1)
	if err != nil {
		return err
	}

	accessToken0.R.SubjectIdentityUser = identityUser1
	accessToken0.R.Loaded.SubjectIdentityUser = true

	return nil
}

func (accessToken0 *AccessToken) AttachSubjectIdentityUser(ctx context.Context, exec bob.Executor, identityUser1 *IdentityUser) error {
	var err error

	_, err = attachAccessTokenSubjectIdentityUser0(ctx, exec, 1, accessToken0, identityUser1)
	if err != nil {
		return err
	}

	accessToken0.R.SubjectIdentityUser = identityUser1
	accessToken0.R.Loaded.SubjectIdentityUser = true

	return nil
}

type accessTokenWhere[Q psql.Filterable] struct {
	cols        accessTokenColumns
	ID          psql.WhereMod[Q, string]
	CreatedAt   psql.WhereMod[Q, time.Time]
	Subject     psql.WhereMod[Q, string]
	Name        psql.WhereMod[Q, string]
	Prefix      psql.WhereMod[Q, string]
	SecretHash  psql.WhereMod[Q, string]
	Scopes      psql.WhereMod[Q, types.JSON[[]string]]
	ExpiresAt   psql.WhereNullMod[Q, time.Time]
	LastUsedAt  psql.WhereNullMod[Q, time.Time]
	RevokedAt   psql.WhereNullMod[Q, time.Time]
	Integration psql.WhereMod[Q, bool]
	CreatedBy   psql.WhereMod[Q, string]
	R           accessTokenWhereR[Q]
}

func (accessTokenWhere[Q]) AliasedAs(alias string) accessTokenWhere[Q] {
	return buildAccessTokenWhere[Q](buildAccessTokenColumns(alias))
}

func buildAccessTokenWhere[Q psql.Filterable](cols accessTokenColumns) accessTokenWhere[Q] {
	return accessTokenWhere[Q]{
		cols:        cols,
		ID:          psql.Where[Q, string](cols.ID.Expression),
		CreatedAt:   psql.Where[Q, time.Time](cols.CreatedAt.Expression),
		Subject:     psql.Where[Q, string](cols.Subject.Expression),
		Name:        psql.Where[Q, string](cols.Name.Expression),
		Prefix:      psql.Where[Q, string](cols.Prefix.Expression),
		SecretHash:  psql.Where[Q, string](cols.SecretHash.Expression),
		Scopes:      psql.Where[Q, types.JSON[[]string]](cols.Scopes.Expression),
		ExpiresAt:   psql.WhereNull[Q, time.Time](cols.ExpiresAt.Expression),
		LastUsedAt:  psql.WhereNull[Q, time.Time](cols.LastUsedAt.Expression),
		RevokedAt:   psql.WhereNull[Q, time.Time](cols.RevokedAt.Expression),
		Integration: psql.Where[Q, bool](cols.Integration.Expression),
		CreatedBy:   psql.Where[Q, string](cols.CreatedBy.Expression),
		R:           accessTokenWhereR[Q]{cols: cols},
	}
}

// accessTokenWhereR holds the relationship-based filters of
// accessTokenWhere under the R namespace — mirroring the model's
// R struct — so they cannot collide with column-based filter fields.
type accessTokenWhereR[Q psql.Filterable] struct {
	cols accessTokenColumns
}

// HasSubjectIdentityUser filters parents that have a matching SubjectIdentityUser using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to IdentityUsers).
func (w accessTokenWhereR[Q]) HasSubjectIdentityUser(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := psql.Select(
		sm.Columns(psql.Raw("1")),
		sm.From(IdentityUsers.NameExpr()),
		sm.Where(IdentityUsers.Columns.ID.EQ(w.cols.Subject)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: psql.Exists(q)}
}
